Let $\Sigma$ be a surface of revolution and let $\Gamma$ be the corresponding profile curve in $\mathbb{R}^{2}_{+}$. 
    \begin{itemize}
        \item[(i)] When an arc, $\Gamma$ can be written as the graph of a function $u:[a,b] \to \mathbb{R}_{+}$ over the $x$-axis, then we refer to the function $u(x)$ as a \emph{horizontal graph function} and its image as a \emph{horizontal graph}.
        \item[(ii)] When an arc, $\Gamma$ can be written as the graph of a function $v:[c,d] \to \mathbb{R}_{+}$ over the $r$-axis, then we refer to the function $v(r)$ as a \emph{vertical graph function} and its image as a \emph{vertical graph}.
    \end{itemize}

Let $\Omega \subset \mathbb{R}^{n}, I\subset \mathbb{R}$ be  open domains and let $w : \Omega \times I \to \mathbb{R}$ be a one-parameter family of smooth functions, then one may  check that the graphs of $w(\cdot,t)$ evolve by mean curvature flow if and only if 
    \begin{equation}\label{eq:full_graph_equation} 
        \displaystyle\frac{\partial w}{\partial t} = \left(\delta^{ij} - \frac{w_{x_{i}}w_{x_{j}}}{1+ |Dw|^{2}}\right)w_{x_{i}x_{j}}.
    \end{equation}
    Equation \eqref{eq:full_graph_equation} is the standard graphical mean curvature flow equation, but we will refer to it here as the \emph{full graph equation} for reasons that would be clear by the subsequent definitions.

Let $\{\Sigma_{t}\}_{t \in [0,T)}$ be a mean curvature flow where each $\Sigma_{t}$ is a surface of revolution.
    \begin{itemize}
        \item[(i)] If the associated profile curves $\Gamma_t$ can be written as a horizontal graph $u(x,t)$ over some fixed interval for a short time,  from \eqref{eq:mean_curvature_sum1} and \eqref{eq:full_graph_equation}, it is easily checked that $u(x,t)$ will satisfy
        \begin{equation}\label{eq:horizontal_graph_equation}
        \displaystyle\frac{\partial u}{\partial t} = \frac{u_{xx}}{1 + u_{x}^{2}} - \frac{n-1}{u}.
        \end{equation}
        We refer to equation \eqref{eq:horizontal_graph_equation} as the \emph{horizontal graph equation}.
        \item[(ii)] If the associated profile curves $\Gamma_{t}$ can be written as a vertical graph $v(r,t)$ over some fixed interval for a short time, from \eqref{eq:mean_curvature_sum2} and \eqref{eq:full_graph_equation}, it is easily checked that $v(r,t)$ will satisfy
        \begin{equation}\label{eq:vertical_graph_equation}
            \displaystyle\frac{\partial v}{\partial t} = \frac{v_{rr}}{1 + v_{r}^{2}} + (n-1)\frac{v_{r}}{r}. 
        \end{equation}
        We refer to equation \eqref{eq:vertical_graph_equation} as the \emph{vertical graph equation}.
    \end{itemize}

\label{def:slings}
    Suppose $\Gamma$ is either $\mathfrak{R}$, $\mathfrak{U}$ or $\mathfrak{T}$ which contains the sphere $B_{h}(C)$, where $C = 0$ if $\Gamma$ is equal to $\mathfrak{R}$ or $\mathfrak{U}$ and $C > 0$ if $\Gamma = \mathfrak{T}$. For integers $j\geq \max\{2h,C\}$, consider the rectangle $\Box_j\doteqdot[-j,j]\times[0,j]$. Define the compact curve $\Gamma^j$ such that $\Gamma^j\cap\Box_j=\Gamma\cap\Box_j$, $\Gamma^j\cap\Box_{j+1}=\Gamma^j$ and 
    \begin{enumerate}
        \item $\Gamma^j\cap(\Box_{j+1}\setminus\Box_{j})$ can be represented as a monotone graph, over the $x$-axis, in the case that $\Gamma = \mathfrak{R}$,
        \item $\Gamma^{j} \cap (\Box_{j+1} \setminus \Box_{j})$ can be represented as a smooth even graph, over the $x$-axis, with a unique local maximum at $x = 0$ in the case that $\Gamma = \mathfrak{U}$ or $\Gamma = \mathfrak{T}$.
    \end{enumerate}
    We shall refer to the curves $\Gamma^{j}$ as \emph{compact slings}. In keeping with earlier notation, given a compact sling $\mathfrak{R}^{j}$, $\mathfrak{U}^{j}$ or $\mathfrak{T}^{j}$ we will write $\mathcal{R}^{j}$, $\mathcal{U}^{j}$ or $\mathcal{T}^{j}$ for the corresponding (compact) surfaces of revolution. By abuse of notation, we shall also refer to the corresponding compact surfaces of revolution as compact slings.

\label{lem:compact1}
    For any decreasing sequence of times $t_j\downarrow0$, there exists a sequence of numbers $x_j$ and $r_j$, such that the following holds. After passing to a subsequence, the  slingshots,  $\mathfrak{R}^j_t$ and $\mathfrak{U}^{j}_t$,  satisfy 
    \begin{equation*}
        \mathfrak{R}^k_t\subset[-a,x_j]\times[0,b],\quad\forall k\geq j,\text{ and }t\geq t_j,
    \end{equation*} and
    \begin{equation*}
        \mathfrak{U}^k_t\subset[-d,d]\times[0,r_j],\quad\forall k\geq j,\text{ and }t\geq t_j,
    \end{equation*}
    respectively.

\label{lem:compact2}
    For any decreasing sequence of times $t_j\downarrow0$, there exists a sequence of numbers $x_j$, such that, after passing to a subsequence, the slingshots $\mathfrak{T}_t^j$, satisfy \begin{equation*}
        \mathfrak{T}^k_t\subset[-L,L]\times[0,x_j],\quad\forall k\geq j,\text{ and }t\geq t_j.
    \end{equation*}

\label{prop:curvrain}
    Suppose $\mathcal{R}_0$ is a raindrop hypersurface satisfying Definition 3.1. Let $0<t_{1} < t_0<\frac{3h^2}{8n}$. Then, for every integer $m\geq0$, there exists a constant $c_m$ depending only on the initial data, $t_{0}$ and $t_{1}$ such that
    \begin{equation}
        \sup_{p\in\mathcal{R}^{k}_t}|\nabla^mA(p)|^2\leq c_m,
    \end{equation} for all $t\in[t_1,t_0]$ and all $k$ sufficiently large.

\label{prop:curvufo}
    Suppose $\mathcal{U}_0$ is a UFO hypersurface satisfying Definition \ref{def:UFOIC}. Let $0<t_{1}<t_0<\frac{3h^2}{8n}$. Then, for every integer $m\geq0$, there exists a constant $c_m$ depending only on the initial data, $t_{0}$ and $t_{1}$ such that\begin{equation}
        \sup_{p\in\mathcal{U}^k_t}|\nabla^mA|^2\leq c_m,
    \end{equation} for all $t\in[t_1,t_0]$ and all $k$ sufficiently large.

\label{prop:curvtor}
    Suppose $\mathcal{T}_0$ is a stretched torus hypersurface satisfying Definition \ref{def:stretchedtorusIC}. Let $0<t_{1} < t_0<(1-\alpha^{2})\min\{\frac{h^2}{2n},\frac{\ell^2}{2(n-1)}\}$ for any \(\alpha \in (0,1)\). Then, for every integer $m\geq0$, there exists a constant $c_m$ depending only on the initial data, $t_{0}$ and $t_{1}$ such that
    \begin{equation}
        \sup_{p\in\mathcal{T}^k_t}|\nabla^mA|^2\leq c_m,
    \end{equation} for all $t\in[t_1,t_0]$ and all $k$ sufficiently large.
